-- Seed replacement presets after retiring the old legacy set.

INSERT INTO email_template_preset (name, category, html_structure, description, is_deleted, created_at, updated_at)
SELECT 'Studio Minimal', 'MINIMAL', '<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><style>body{margin:0;padding:0;background:#eef2f7;font-family:Arial,sans-serif;color:#1e293b}.email-shell{width:100%;padding:32px 16px;box-sizing:border-box}.email-card{max-width:680px;margin:0 auto;background:#ffffff;border:1px solid #d7e0ea;border-radius:24px;overflow:hidden}.email-topbar{height:6px;background:linear-gradient(90deg,{{primaryColor}},{{primaryColorDark}})}.email-header{padding:40px 40px 20px 40px}.email-eyebrow{margin:0 0 10px 0;font-size:12px;letter-spacing:0.16em;text-transform:uppercase;color:#64748b}.email-title{margin:0;font-size:30px;line-height:1.2;color:#0f172a}.email-subtitle{margin:14px 0 0 0;font-size:16px;line-height:1.6;color:#475569}.email-body{padding:0 40px 24px 40px;font-size:16px;line-height:1.8;color:#334155}.email-body p{margin:0 0 16px 0}.email-cta{padding:0 40px 40px 40px}.btn{display:inline-block;padding:14px 24px;border-radius:999px;background:{{primaryColor}};color:#ffffff !important;text-decoration:none;font-weight:700}.email-footer{padding:22px 40px 36px 40px;border-top:1px solid #e2e8f0;font-size:13px;line-height:1.7;color:#64748b}.email-footer strong{color:#334155}@media only screen and (max-width:600px){.email-shell{padding:16px 8px}.email-header,.email-body,.email-cta,.email-footer{padding-left:24px;padding-right:24px}.email-title{font-size:24px}}@media (prefers-color-scheme:dark){body{background:#020617;color:#e2e8f0}.email-card{background:#0f172a;border-color:#1e293b}.email-eyebrow{color:#94a3b8}.email-title{color:#f8fafc}.email-subtitle,.email-body{color:#cbd5e1}.email-footer{border-top-color:#1e293b;color:#94a3b8}.email-footer strong{color:#f8fafc}}</style></head><body><div class="email-shell"><div class="email-card"><div class="email-topbar"></div><div class="email-header"><p class="email-eyebrow">{{companyName}}</p><h1 class="email-title">{{title}}</h1><p class="email-subtitle">{{subtitle}}</p></div><div class="email-body">{{content}}</div><div class="email-cta"><a href="{{buttonLink}}" class="btn">{{buttonText}}</a></div><div class="email-footer"><strong>{{companyName}}</strong><br>{{companyAddress}}<br>{{currentYear}}</div></div></div></body></html>', 'Preset epure et premium pour les messages generaux ou transactionnels.', FALSE, NOW(), NOW()
WHERE NOT EXISTS (
    SELECT 1 FROM email_template_preset WHERE name = 'Studio Minimal' AND category = 'MINIMAL'
);

INSERT INTO email_template_preset (name, category, html_structure, description, is_deleted, created_at, updated_at)
SELECT 'Aurora Modern', 'MODERN', '<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><style>body{margin:0;padding:0;background:#eff6ff;font-family:Segoe UI,Roboto,sans-serif;color:#102033}.wrap{width:100%;padding:28px 14px;box-sizing:border-box}.card{max-width:700px;margin:0 auto;background:#ffffff;border-radius:28px;overflow:hidden;box-shadow:0 24px 60px rgba(15,23,42,0.10)}.hero{padding:44px 40px;background:linear-gradient(135deg,{{primaryColor}},{{primaryColorDark}});color:#ffffff}.hero-grid{display:table;width:100%}.hero-copy,.hero-meta{display:table-cell;vertical-align:top}.hero-meta{text-align:right;font-size:13px;letter-spacing:0.08em;text-transform:uppercase;opacity:0.8}.hero-title{margin:0 0 12px 0;font-size:32px;line-height:1.15}.hero-subtitle{margin:0;font-size:16px;line-height:1.7;max-width:460px}.body{padding:36px 40px 18px 40px;font-size:16px;line-height:1.8;color:#334155}.body p{margin:0 0 16px 0}.panel{margin:0 40px 28px 40px;padding:18px 20px;border:1px solid rgba(107,70,193,0.16);border-radius:18px;background:rgba(107,70,193,0.06);font-size:14px;line-height:1.7;color:#475569}.cta{padding:0 40px 40px 40px}.btn{display:inline-block;padding:15px 28px;border-radius:16px;background:#0f172a;color:#ffffff !important;text-decoration:none;font-weight:700}.footer{padding:24px 40px 34px 40px;background:#f8fafc;color:#64748b;font-size:13px;line-height:1.7}.footer strong{color:#334155}@media only screen and (max-width:600px){.wrap{padding:16px 8px}.hero,.body,.cta,.footer{padding-left:24px;padding-right:24px}.panel{margin-left:24px;margin-right:24px}.hero-grid,.hero-copy,.hero-meta{display:block;text-align:left}.hero-meta{margin-top:18px}.hero-title{font-size:26px}}@media (prefers-color-scheme:dark){body{background:#020617;color:#e2e8f0}.card{background:#0f172a;box-shadow:none}.body{color:#cbd5e1}.panel{background:rgba(148,163,184,0.08);border-color:rgba(148,163,184,0.18);color:#cbd5e1}.btn{background:#ffffff;color:#0f172a !important}.footer{background:#111827;color:#94a3b8}.footer strong{color:#f8fafc}}</style></head><body><div class="wrap"><div class="card"><div class="hero"><div class="hero-grid"><div class="hero-copy"><h1 class="hero-title">{{title}}</h1><p class="hero-subtitle">{{subtitle}}</p></div><div class="hero-meta">{{companyName}}</div></div></div><div class="body">{{content}}</div><div class="panel">{{signature}}</div><div class="cta"><a href="{{buttonLink}}" class="btn">{{buttonText}}</a></div><div class="footer"><strong>{{companyName}}</strong><br>{{companyAddress}}<br>{{currentYear}}</div></div></div></body></html>', 'Preset moderne avec hero structure, panneau d infos et CTA fort.', FALSE, NOW(), NOW()
WHERE NOT EXISTS (
    SELECT 1 FROM email_template_preset WHERE name = 'Aurora Modern' AND category = 'MODERN'
);

