SELECT 'Executive Frame', 'CORPORATE', '<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><style>body{margin:0;padding:0;background:#f4f4f1;font-family:Georgia,Times New Roman,serif;color:#292524}.frame{width:100%;padding:30px 14px;box-sizing:border-box}.card{max-width:700px;margin:0 auto;background:#ffffff;border:1px solid #d6d3d1}.masthead{padding:28px 34px;border-bottom:4px solid {{primaryColor}}}.masthead-brand{margin:0;font-size:14px;letter-spacing:0.18em;text-transform:uppercase;color:#78716c}.masthead-title{margin:16px 0 0 0;font-size:30px;line-height:1.25;color:#1c1917}.intro{padding:18px 34px 0 34px;font-size:15px;line-height:1.8;color:#57534e}.body{padding:18px 34px 22px 34px;font-size:16px;line-height:1.9;color:#44403c}.body p{margin:0 0 16px 0}.rule{margin:0 34px;border-top:1px solid #e7e5e4}.cta{padding:24px 34px 10px 34px}.btn{display:inline-block;padding:12px 24px;border:1px solid {{primaryColor}};color:{{primaryColor}} !important;text-decoration:none;font-weight:700;border-radius:999px}.signature{padding:18px 34px 28px 34px;font-size:14px;line-height:1.8;color:#57534e}.footer{padding:20px 34px 30px 34px;background:#fafaf9;color:#78716c;font-size:12px;line-height:1.7}@media only screen and (max-width:600px){.frame{padding:16px 8px}.masthead,.intro,.body,.cta,.signature,.footer{padding-left:22px;padding-right:22px}.masthead-title{font-size:24px}.rule{margin-left:22px;margin-right:22px}}@media (prefers-color-scheme:dark){body{background:#111827;color:#e5e7eb}.card{background:#111827;border-color:#374151}.masthead-brand,.footer{color:#9ca3af}.masthead-title{color:#f9fafb}.intro,.body,.signature{color:#d1d5db}.rule{border-top-color:#374151}.btn{border-color:#93c5fd;color:#93c5fd !important}.footer{background:#0f172a}}</style></head><body><div class="frame"><div class="card"><div class="masthead"><p class="masthead-brand">{{companyName}}</p><h1 class="masthead-title">{{title}}</h1></div><div class="intro">{{subtitle}}</div><div class="body">{{content}}</div><div class="rule"></div><div class="cta"><a href="{{buttonLink}}" class="btn">{{buttonText}}</a></div><div class="signature">{{signature}}</div><div class="footer">{{companyName}} - {{companyAddress}} - {{currentYear}}</div></div></div></body></html>', 'Preset institutionnel pour convocations, decisions et messages officiels.', FALSE, NOW(), NOW()
WHERE NOT EXISTS (
    SELECT 1 FROM email_template_preset WHERE name = 'Executive Frame' AND category = 'CORPORATE'
);

